actions.script:
for (const geoId of [postalAddress?.countyGeoId, postalAddress?.stateProvinceGeoId, postalAddress?.countryGeoId, postalAddress?.postalCodeGeoId]) {
    if (geoId && !geoIdSet.includes(geoId)) geoIdSet.push(geoId)
}

// countryCode, areaCode, and extension should contain only digits
if (countryCode) countryCode = countryCode.trim().replace(/\D/g, "")
if (areaCode) areaCode = areaCode.trim().replace(/\D/g, "")
if (extension) extension = extension.trim().replace(/\D/g, "")
if (contactNumber) {
    // trim to make sure
    contactNumber = contactNumber.trim()
    // if contactNumber contains spaces change them to dashes
    contactNumber = contactNumber.replace(/\s/g, "-")
    // contactNumber should only contain digits, and '.' or '-'
    contactNumber = contactNumber.replace(/[^\d\.-]/g, "")
    // NOTE: the Groovy original replaced dots with dashes when both are present but discarded the result, so
    //     this has no effect and is not ported
    contactNumber = contactNumber.trim().replace(/--/g, "-")
    // if no dots or dashes and length is 7 add a dash after 3 digits
    if (!contactNumber.includes('-') && !contactNumber.includes('.') && contactNumber.length === 7)
        contactNumber = contactNumber.substring(0, 3) + '-' + contactNumber.substring(3)
}
// validation by country codes, see https://en.wikipedia.org/wiki/List_of_country_calling_codes
if ((countryCode == '1' || countryCode == '+1') && contactNumber) {
    // North America Numbering Plan (USA, Canada, etc) - 3 digit areaCode, 7 digit contactNumber
    // see https://en.wikipedia.org/wiki/North_American_Numbering_Plan
    isValid = true
    if (areaCode) {
        if (areaCode.length !== 3) {
            isValid = false
            ec.message.addMessage(`Area code ${areaCode} not valid for North America, should be 3 digits`, "warning")
        }
        if (areaCode.charAt(0) === '0' || areaCode.charAt(0) === '1') {
            isValid = false
            ec.message.addMessage(`Area code ${areaCode} not valid for North America, should not start with 0 or 1`, "warning")
        }
    } else {
        isValid = false
        ec.message.addMessage("No area code specified, for North America must have a 3 digit area code not starting with 0 or 1", "warning")
    }
    if (contactNumber) {
        const contactNumberOnly = contactNumber.trim().replace(/\D/g, "")
        if (contactNumberOnly.length !== 7) {
            isValid = false
            ec.message.addMessage(`Contact number ${contactNumber} not valid for North America, should be 7 digits`, "warning")
        }
        if (contactNumberOnly.charAt(0) === '0' || contactNumberOnly.charAt(0) === '1') {
            isValid = false
            ec.message.addMessage(`Contact number ${contactNumber} not valid for North America, should not start with 0 or 1`, "warning")
        }
    } else {
        isValid = false
        ec.message.addMessage("No contact number specified, for North America must have a 7 digit contact number not starting with 0 or 1", "warning")
    }
}
// TODO: add validation for other countryCode values

if.script:
let ef = ec.entity.find("mantle.party.contact.PartyContactMech").condition({partyId: partyId, contactMechId: contactMechId})
if (oldContactMechPurposeId) ef = ef.condition("contactMechPurposeId", oldContactMechPurposeId)
// expire each matching record with an update, so entity ECAs run
const nowTimestamp = ec.user.nowTimestamp
for (const pcm of ef.list()) { pcm.set("thruDate", nowTimestamp); pcm.update() }

// an update, so entity ECAs run
for (const pcm of Array.from(pcmList)) {
    if (pcm.allowSolicitation === allowSolicitation) continue
    pcm.set("allowSolicitation", allowSolicitation)
    pcm.update()
}

actions.script:
let ef = ec.entity.find("mantle.party.contact.PartyContactMech").condition({partyId: partyId, contactMechId: contactMechId})
if (contactMechPurposeId) ef = ef.condition("contactMechPurposeId", contactMechPurposeId)
// expire each matching record with an update, so entity ECAs run
const nowTimestamp = ec.user.nowTimestamp
for (const pcm of ef.list()) { pcm.set("thruDate", nowTimestamp); pcm.update() }
